import{_ as t,o,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"Report cards and lesson log","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/bulletins-et-cahier-texte.md","filePath":"src/en/guide/enseignant/bulletins-et-cahier-texte.md"}'),s={name:"en/guide/enseignant/bulletins-et-cahier-texte.md"};function n(i,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="report-cards-and-lesson-log" tabindex="-1">Report cards and lesson log <a class="header-anchor" href="#report-cards-and-lesson-log" aria-label="Permalink to &quot;Report cards and lesson log&quot;">​</a></h1><p>This page covers two distinct tasks: writing the appreciations that will appear on your students&#39; report cards, and keeping the lesson log that tracks what was covered in your sessions and the homework assigned.</p><h2 id="write-per-subject-appreciations" tabindex="-1">Write per-subject appreciations <a class="header-anchor" href="#write-per-subject-appreciations" aria-label="Permalink to &quot;Write per-subject appreciations&quot;">​</a></h2><p>For each of your class/subject assignments, you can enter one appreciation per student for a given academic period. The homeroom teacher can also do it for every subject of their class.</p><ol><li>From the <strong>Evaluations</strong> list, click <strong>Bulletins</strong> on the row of an evaluation for the relevant class and subject.</li><li>Choose the <strong>academic period</strong> from the selector at the top of the page.</li><li>For each student, enter their <strong>Appreciation</strong> in the text field (optional). If the school set up <a href="/era-guide/en/guide/admin/bulletins.html#appreciation-rubrics">appreciation rubrics</a> (Attitude, Progression, Advice…), each student has one field per rubric, all optional.</li><li>Click <strong>Save</strong> — every appreciation in the list is saved at once.</li></ol><h2 id="end-of-period-appreciation" tabindex="-1">Write the end-of-period general appreciation (homeroom teacher) <a class="header-anchor" href="#end-of-period-appreciation" aria-label="Permalink to &quot;Write the end-of-period general appreciation (homeroom teacher) {#end-of-period-appreciation}&quot;">​</a></h2><p>If you are the homeroom teacher of a class, you also enter an end-of-period general appreciation, separate from the per-subject ones.</p><ol><li>Open <strong>Teaching → My homeroom class</strong>, then click <strong>End-of-period appreciations</strong> next to the relevant class.</li><li>Choose the <strong>academic period</strong> from the selector at the top of the page.</li><li>For each student, fill in the <strong>General appreciation</strong> and <strong>Conduct</strong> fields, and check any relevant flags: <strong>Congratulations</strong>, <strong>Compliments</strong>, <strong>Encouragements</strong>, <strong>Work warning</strong>, <strong>Conduct warning</strong>.</li><li>If the school has set up <a href="/era-guide/en/guide/admin/bulletins.html#report-card-activities">report card activities</a>, tick the student&#39;s: they are printed on their report card.</li><li>Click <strong>Save</strong>.</li></ol><h2 id="view-grade-summaries" tabindex="-1">View grade summaries <a class="header-anchor" href="#view-grade-summaries" aria-label="Permalink to &quot;View grade summaries&quot;">​</a></h2><p><strong>Teaching → Grade summaries</strong> shows the classes you teach:</p><ul><li>for each subject you teach there, its <strong>mark sheet</strong>: every evaluation of the period, each student&#39;s grade as entered, and their subject average, the report card&#39;s;</li><li>if you are the class&#39;s <strong>homeroom teacher</strong>, the whole class&#39;s <strong>grade summary</strong> (each student in each subject, with their overall average), every subject&#39;s mark sheet, and each student&#39;s grade report.</li></ul><p>Each screen downloads as a PDF or an Excel file, with the ranks. The Excel file of a subject you teach is also how you <strong>import</strong> your grades and appreciations: fill it in, then send it back with <strong>Import</strong>. The homeroom teacher imports the grades and appreciations of every subject of their class the same way, as well as the council appreciations; they can also import <strong>all of a student&#39;s subjects</strong> in one file, with the icons next to the student&#39;s name in the class summary. The class summary also gives, in one file each, <strong>all subjects</strong> (PDF or Excel) and the <strong>council appreciations</strong> (PDF), which you also find on the appreciations page. From the <strong>Evaluations</strong> list, <strong>Excel file</strong> goes straight to the subject&#39;s mark sheet. The details are in the admin guide: <a href="/era-guide/en/guide/admin/bulletins.html#grade-summaries">Grade summaries</a> and <a href="/era-guide/en/guide/admin/bulletins.html#import-from-excel">Import from Excel</a>.</p><h2 id="keep-the-lesson-log" tabindex="-1">Keep the lesson log <a class="header-anchor" href="#keep-the-lesson-log" aria-label="Permalink to &quot;Keep the lesson log&quot;">​</a></h2><p>The lesson log tracks, session by session, what was covered in class and the homework assigned, for all your class/subject assignments.</p><ol><li>Open <strong>Teaching → Lesson log</strong>, then click <strong>New entry</strong>.</li><li>Choose the <strong>Class</strong> and <strong>Subject</strong>, then fill in the <strong>Date</strong>.</li><li>Describe the <strong>Content covered</strong> (required) and, if relevant, the <strong>Homework</strong> assigned.</li><li>Optionally attach a <strong>Document</strong> (PDF, JPG or PNG).</li><li>Click <strong>Save</strong>.</li></ol><p>The list of entries can be filtered by keyword (searching the content) or by class, and shows each entry&#39;s date, class, subject, content and homework. From this list:</p><ul><li>the <strong>Document</strong> button downloads the attachment if an entry has one;</li><li><strong>Edit</strong> reopens the entry to correct it (you can replace or remove the attached document there);</li><li><strong>Delete</strong> permanently removes it, after confirmation — this cannot be undone.</li></ul>',17)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
